    "question": "Q36. Lucas reagent (a solution of anhydrous $\\text{ZnCl}_2$ in concentrated $\\text{HCl}$) is used to distinguish between primary, secondary, and tertiary alcohols. An alcohol produces immediate turbidity at room temperature. The alcohol is:",
    "options": {
      "A": "Secondary alcohol (e.g., propan-2-ol)",
      "B": "Primary alcohol (e.g., propan-1-ol)",
      "C": "Methanol",
      "D": "Tertiary alcohol (e.g., 2-methylpropan-2-ol)"
    },
    "optionsList": [
      "Secondary alcohol (e.g., propan-2-ol)",
      "Primary alcohol (e.g., propan-1-ol)",
      "Methanol",
      "Tertiary alcohol (e.g., 2-methylpropan-2-ol)"
    ],
    "correctAnswer": "D",
    "correctIndex": 3,
    "explanation": "1. CONCEPT & PRINCIPLE:\nLucas test for distinguishing alcohols based on carbocation stability.\n\n2. GIVEN INFORMATION / DATA:\nAlcohol reacting with $\\text{conc. } HCl + \\text{anhydrous } ZnCl_2$ at room temperature.\n\n3. FORMULA / EQUATION:\n$R-OH + HCl \\xrightarrow{\\text{anh. } ZnCl_2} R-Cl\\downarrow \\text{ (turbidity)} + H_2O$\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. Lucas reagent converts alcohols to insoluble alkyl chlorides, which appear as white turbidity or oily droplets in the aqueous layer.\n2. The reaction proceeds via an $S_N1$ mechanism where the rate is governed by the stability of the intermediate carbocation $R^+$.\n3. Tertiary alcohols form very stable $3^\\circ$ carbocations and react almost instantaneously, producing immediate turbidity at room temperature.\n4. Secondary alcohols produce turbidity within 5 to 10 minutes.\n5. Primary alcohols do not produce turbidity at room temperature and require prolonged heating to react.\n\n5. FINAL CONCLUSION:\nTertiary alcohol (e.g., 2-methylpropan-2-ol)\n\n6. OPTION ANALYSIS & COMMON TRAPS:\nSecondary alcohols require 5-10 minutes; primary alcohols and methanol require heating to produce turbidity.",
    "solutionStructured": {
      "concept": "Lucas test for distinguishing alcohols based on carbocation stability.",
      "given": "Alcohol reacting with $\\text{conc. } HCl + \\text{anhydrous } ZnCl_2$ at room temperature.",
      "formula": "$R-OH + HCl \\xrightarrow{\\text{anh. } ZnCl_2} R-Cl\\downarrow \\text{ (turbidity)} + H_2O$",
      "stepByStep": "1. Lucas reagent converts alcohols to insoluble alkyl chlorides, which appear as white turbidity or oily droplets in the aqueous layer.\n2. The reaction proceeds via an $S_N1$ mechanism where the rate is governed by the stability of the intermediate carbocation $R^+$.\n3. Tertiary alcohols form very stable $3^\\circ$ carbocations and react almost instantaneously, producing immediate turbidity at room temperature.\n4. Secondary alcohols produce turbidity within 5 to 10 minutes.\n5. Primary alcohols do not produce turbidity at room temperature and require prolonged heating to react.",
      "finalAnswer": "Tertiary alcohol (e.g., 2-methylpropan-2-ol)",
      "whyOtherOptionsWrong": "Secondary alcohols require 5-10 minutes; primary alcohols and methanol require heating to produce turbidity."
    },
