    "question": "Q38. In the Reimer-Tiemann reaction, phenol is treated with chloroform in aqueous sodium hydroxide at $340\\text{ K}$, followed by acidification, to yield salicylaldehyde. The electrophile involved in this reaction is:",
    "options": {
      "A": "Formyl cation ($^+\\text{CHO}$)",
      "B": "Dichlorocarbene ($:\\text{CCl}_2$)",
      "C": "Trichloromethyl anion ($^-\\text{CCl}_3$)",
      "D": "Chloronium ion ($\\text{Cl}^+$)"
    },
    "optionsList": [
      "Formyl cation ($^+\\text{CHO}$)",
      "Dichlorocarbene ($:\\text{CCl}_2$)",
      "Trichloromethyl anion ($^-\\text{CCl}_3$)",
      "Chloronium ion ($\\text{Cl}^+$)"
    ],
    "correctAnswer": "B",
    "correctIndex": 1,
    "explanation": "1. CONCEPT & PRINCIPLE:\nReactive intermediate and electrophile in the Reimer-Tiemann reaction.\n\n2. GIVEN INFORMATION / DATA:\nPhenol + $CHCl_3 + NaOH$ at $60-70^\\circ\\text{C} \\rightarrow$ Salicylaldehyde.\n\n3. FORMULA / EQUATION:\nGeneration of carbene: $OH^- + CHCl_3 \\rightleftharpoons H_2O + ^-CCl_3 \\xrightarrow{-\\text{Cl}^-} :CCl_2$\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. Hydroxide ion abstracts the acidic proton from chloroform ($CHCl_3$) to form the trichloromethyl carbanion ($^-CCl_3$).\n2. The carbanion undergoes spontaneous alpha-elimination, ejecting a chloride ion ($Cl^-$) to generate neutral dichlorocarbene ($:CCl_2$).\n3. Dichlorocarbene possesses an incomplete sextet of electrons around carbon (6 valence electrons), acting as a potent neutral electrophile.\n4. Dichlorocarbene attacks the electron-rich ortho position of the resonance-activated phenoxide ion, yielding an intermediate benzylidene dichloride that hydrolyzes to form salicylaldehyde (2-hydroxybenzaldehyde).\n\n5. FINAL CONCLUSION:\nDichlorocarbene ($:\\text{CCl}_2$)\n\n6. OPTION ANALYSIS & COMMON TRAPS:\nFormyl cation is not generated; trichloromethyl anion is a nucleophilic precursor, not the active electrophile.",
    "solutionStructured": {
      "concept": "Reactive intermediate and electrophile in the Reimer-Tiemann reaction.",
      "given": "Phenol + $CHCl_3 + NaOH$ at $60-70^\\circ\\text{C} \\rightarrow$ Salicylaldehyde.",
      "formula": "Generation of carbene: $OH^- + CHCl_3 \\rightleftharpoons H_2O + ^-CCl_3 \\xrightarrow{-\\text{Cl}^-} :CCl_2$",
      "stepByStep": "1. Hydroxide ion abstracts the acidic proton from chloroform ($CHCl_3$) to form the trichloromethyl carbanion ($^-CCl_3$).\n2. The carbanion undergoes spontaneous alpha-elimination, ejecting a chloride ion ($Cl^-$) to generate neutral dichlorocarbene ($:CCl_2$).\n3. Dichlorocarbene possesses an incomplete sextet of electrons around carbon (6 valence electrons), acting as a potent neutral electrophile.\n4. Dichlorocarbene attacks the electron-rich ortho position of the resonance-activated phenoxide ion, yielding an intermediate benzylidene dichloride that hydrolyzes to form salicylaldehyde (2-hydroxybenzaldehyde).",
      "finalAnswer": "Dichlorocarbene ($:\\text{CCl}_2$)",
      "whyOtherOptionsWrong": "Formyl cation is not generated; trichloromethyl anion is a nucleophilic precursor, not the active electrophile."
    },
