    "question": "Q42. Phenol is significantly more acidic than aliphatic alcohols like ethanol because:",
    "options": {
      "A": "Phenol has a higher molecular weight than ethanol",
      "B": "The phenoxide ion is stabilized by resonance delocalization of negative charge into the benzene ring",
      "C": "The oxygen atom in phenol has no lone pairs of electrons",
      "D": "Ethanol easily loses a hydride ion instead of a proton"
    },
    "optionsList": [
      "Phenol has a higher molecular weight than ethanol",
      "The phenoxide ion is stabilized by resonance delocalization of negative charge into the benzene ring",
      "The oxygen atom in phenol has no lone pairs of electrons",
      "Ethanol easily loses a hydride ion instead of a proton"
    ],
    "correctAnswer": "B",
    "correctIndex": 1,
    "explanation": "1. CONCEPT & PRINCIPLE:\nAcidity of phenols compared to aliphatic alcohols.\n\n2. GIVEN INFORMATION / DATA:\nIonization equilibrium: $C_6H_5OH \\rightleftharpoons C_6H_5O^- + H^+$ vs $C_2H_5OH \\rightleftharpoons C_2H_5O^- + H^+$.\n\n3. FORMULA / EQUATION:\nPhenoxide ion has 5 contributing resonance structures delocalizing negative charge over ortho and para carbons.\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. When phenol loses a proton, it forms the phenoxide ion ($C_6H_5O^-$).\n2. The negative charge on oxygen is conjugated with the aromatic $\\pi$-electron system and delocalizes over the ortho and para positions of the ring through resonance.\n3. In contrast, in the ethoxide ion ($C_2H_5O^-$), the negative charge is strictly localized on oxygen, and the $+I$ inductive effect of the ethyl group intensifies the negative charge, destabilizing it.\n4. Because the phenoxide conjugate base is markedly more stable than the ethoxide ion, phenol dissociates more readily ($pK_a \\approx 10$ vs $16$ for ethanol).\n5. Hence, phenol is $10^6$ times more acidic than aliphatic alcohols.\n\n5. FINAL CONCLUSION:\nThe phenoxide ion is stabilized by resonance delocalization of negative charge into the benzene ring.\n\n6. OPTION ANALYSIS & COMMON TRAPS:\nMolecular weight does not dictate acidity; oxygen retains two lone pairs in phenol; ethanol loses $H^+$, not hydride $H^-$.",
    "solutionStructured": {
      "concept": "Acidity of phenols compared to aliphatic alcohols.",
      "given": "Ionization equilibrium: $C_6H_5OH \\rightleftharpoons C_6H_5O^- + H^+$ vs $C_2H_5OH \\rightleftharpoons C_2H_5O^- + H^+$.",
      "formula": "Phenoxide ion has 5 contributing resonance structures delocalizing negative charge over ortho and para carbons.",
      "stepByStep": "1. When phenol loses a proton, it forms the phenoxide ion ($C_6H_5O^-$).\n2. The negative charge on oxygen is conjugated with the aromatic $\\pi$-electron system and delocalizes over the ortho and para positions of the ring through resonance.\n3. In contrast, in the ethoxide ion ($C_2H_5O^-$), the negative charge is strictly localized on oxygen, and the $+I$ inductive effect of the ethyl group intensifies the negative charge, destabilizing it.\n4. Because the phenoxide conjugate base is markedly more stable than the ethoxide ion, phenol dissociates more readily ($pK_a \\approx 10$ vs $16$ for ethanol).\n5. Hence, phenol is $10^6$ times more acidic than aliphatic alcohols.",
      "finalAnswer": "The phenoxide ion is stabilized by resonance delocalization of negative charge into the benzene ring.",
      "whyOtherOptionsWrong": "Molecular weight does not dictate acidity; oxygen retains two lone pairs in phenol; ethanol loses $H^+$, not hydride $H^-$."
    },
