    "question": "Q46. Lucas reagent (a solution of anhydrous $\\text{ZnCl}_2$ in concentrated $\\text{HCl}$) is used to distinguish between primary, secondary, and tertiary alcohols. An alcohol produces immediate turbidity at room temperature. The alcohol is:",
