      "given": "Alcohol reacting with $\\text{conc. } HCl + \\text{anhydrous } ZnCl_2$ at room temperature.",
      "formula": "$R-OH + HCl \\xrightarrow{\\text{anh. } ZnCl_2} R-Cl\\downarrow \\text{ (turbidity)} + H_2O$",
