    "question": "Q104. In Williamson ether synthesis, tert-butyl ethyl ether is best prepared by the reaction of:",
    "options": {
      "A": "tert-Butyl bromide with sodium ethoxide",
      "B": "tert-Butyl alcohol with ethanol in concentrated $\\text{H}_2\\text{SO}_4$",
      "C": "Ethyl alcohol with tert-butyl magnesium bromide",
      "D": "Sodium tert-butoxide with ethyl bromide"
    },
    "optionsList": [
      "tert-Butyl bromide with sodium ethoxide",
      "tert-Butyl alcohol with ethanol in concentrated $\\text{H}_2\\text{SO}_4$",
      "Ethyl alcohol with tert-butyl magnesium bromide",
      "Sodium tert-butoxide with ethyl bromide"
    ],
    "correctAnswer": "D",
    "correctIndex": 3,
    "explanation": "1. CONCEPT & PRINCIPLE:\nWilliamson synthesis substrate requirements and competition between substitution ($S_N2$) and elimination ($E2$).\n\n2. GIVEN INFORMATION / DATA:\nTarget ether: $(CH_3)_3C-O-CH_2CH_3$.\n\n3. FORMULA / EQUATION:\nWilliamson rule: Alkyl halide MUST be primary ($1^\\circ$) to avoid E2 elimination.\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. Williamson ether synthesis operates by an $S_N2$ displacement of halide from alkyl halide by alkoxide ion ($R-O^- + R'-X \\rightarrow R-O-R' + X^-$).\n2. If tert-butyl bromide ($3^\\circ$ halide) is treated with sodium ethoxide (a strong base), elimination dominates completely ($E2$), producing isobutylene (2-methylpropene) rather than the ether.\n3. Therefore, the primary alkyl halide (ethyl bromide, $CH_3CH_2Br$) must be attacked by the bulky alkoxide (sodium tert-butoxide, $(CH_3)_3C-O^-Na^+$).\n4. Backside attack on unhindered primary carbon proceeds smoothly via $S_N2$ to give tert-butyl ethyl ether in high yield.\n\n5. FINAL CONCLUSION:\nSodium tert-butoxide with ethyl bromide\n\n6. OPTION ANALYSIS & COMMON TRAPS:\ntert-Butyl bromide + sodium ethoxide yields 2-methylpropene (elimination product); acid dehydration of mixed alcohols yields a complex mixture.",
    "solutionStructured": {
      "concept": "Williamson synthesis substrate requirements and competition between substitution ($S_N2$) and elimination ($E2$).",
      "given": "Target ether: $(CH_3)_3C-O-CH_2CH_3$.",
      "formula": "Williamson rule: Alkyl halide MUST be primary ($1^\\circ$) to avoid E2 elimination.",
      "stepByStep": "1. Williamson ether synthesis operates by an $S_N2$ displacement of halide from alkyl halide by alkoxide ion ($R-O^- + R'-X \\rightarrow R-O-R' + X^-$).\n2. If tert-butyl bromide ($3^\\circ$ halide) is treated with sodium ethoxide (a strong base), elimination dominates completely ($E2$), producing isobutylene (2-methylpropene) rather than the ether.\n3. Therefore, the primary alkyl halide (ethyl bromide, $CH_3CH_2Br$) must be attacked by the bulky alkoxide (sodium tert-butoxide, $(CH_3)_3C-O^-Na^+$).\n4. Backside attack on unhindered primary carbon proceeds smoothly via $S_N2$ to give tert-butyl ethyl ether in high yield.",
      "finalAnswer": "Sodium tert-butoxide with ethyl bromide",
      "whyOtherOptionsWrong": "tert-Butyl bromide + sodium ethoxide yields 2-methylpropene (elimination product); acid dehydration of mixed alcohols yields a complex mixture."
    },
