    "question": "Q113. In the Reimer-Tiemann reaction, phenol is treated with chloroform in aqueous sodium hydroxide at $340\\text{ K}$, followed by acidification, to yield salicylaldehyde. The electrophile involved in this reaction is:",
    "options": {
      "A": "Dichlorocarbene ($:\\text{CCl}_2$)",
      "B": "Formyl cation ($^+\\text{CHO}$)",
      "C": "Trichloromethyl anion ($^-\\text{CCl}_3$)",
      "D": "Chloronium ion ($\\text{Cl}^+$)"
    },
